import{_ as a,o as n,c as d,a4 as s}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20250603212035163.ButoQEFf.png",o="/assets/image-20250603212426601.DbQwpm_h.png",c="/assets/code1-025d79a0d496c38fe2711eb756c3854c2969ef0c.B8E9m9Iy.png",i="/assets/code2-b3fbe8f2e33158607539cd20dc7000eb843ae452.D-VCKMpn.png",r="/assets/code1-7af7b199cad6031acc6fc56bcaaf5880886b9e60.DTGSyFFR.png",p="/assets/code2-583980b1ed1748a7b57c69089c7d80b84f11c59e.D9kn5Oxn.png",l="/assets/image-20250603213217437.Dl52GGUx.png",m="/assets/image-20250603213233676.BX2N8J-9.png",I=JSON.parse('{"title":"CodeBuddy AI 时代的智能编程伙伴","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/CodeBuddy AI 时代的智能编程伙伴/CodeBuddy AI 时代的智能编程伙伴.md","filePath":"AI人工智能/CodeBuddy AI 时代的智能编程伙伴/CodeBuddy AI 时代的智能编程伙伴.md","lastUpdated":1748958402000,"__rawMarkdown":"# CodeBuddy AI 时代的智能编程伙伴\\n\\n## 介绍\\n\\n[CodeBuddy](https://copilot.tencent.com/) 腾讯云主导的开发AI 时代的智能编程伙伴，用自然语言编程，AI 自主完成多文件代码生成和改写，让灵感即刻落地。\\n\\n![image-20250603212035163](assets/image-20250603212035163.png)\\n\\n## 下载安装\\n\\n**CodeBuddy**目前支持在四个编辑器中使用\\n\\n1. vscode\\n2. IDEA\\n3. Visual Studio\\n4. 微信开发者平台 IDE\\n\\n我们都可以在适合自己的编辑器上安装使用，接下来我们主要是通过vscode来演示如何使用。\\n\\n### vscode 安装\\n\\n在插件列表页面搜索下载安装即可。\\n\\n![image-20250603212426601](assets/image-20250603212426601.png)\\n\\n\\n\\n## 全新软件开发智能体：Craft\\n\\n**Craft** 最新和核心的功能，可以使用自然语言进行沟通需求实现功能。\\n\\n<video src=\\"https://dscache.tencent-cloud.cn/upload/uploader/0fdf6ddb51da254941104943c74e4d07-a81302d0a32e711abd5ab9c56638c88bbaee99f4.mp4\\" ></video>\\n\\n## 智能问答：Chat\\n\\n基于海量技术文档进行训练，支持团队自定义知识库管理和模型切换\\n\\n![img](assets/code1-025d79a0d496c38fe2711eb756c3854c2969ef0c.png)\\n\\n## 代码评审：Code Review\\n\\n支持代码批量评审，给出优化建议。自动生成commit message，规范开发流程\\n\\n![img](assets/code2-b3fbe8f2e33158607539cd20dc7000eb843ae452.png)\\n\\n\\n\\n\\n\\n\\n\\n## 外部工具调用：MCP\\n\\n兼容 MCP 开放生态，推动 AI 与外部系统标准化连接，串联端到端的开发全流程\\n\\n![img](assets/code1-7af7b199cad6031acc6fc56bcaaf5880886b9e60.png)\\n\\n## 代码补全：Plus\\n\\n基于上下文理解以及编辑行为，预测下一个改动点，同时给出相应推荐，提升编码效率\\n\\n![img](assets/code2-583980b1ed1748a7b57c69089c7d80b84f11c59e.png)\\n\\n\\n\\n## 实战案例\\n\\n```\\n帮我实现一个二手商品网站\\n```\\n\\n![image-20250603213217437](assets/image-20250603213217437.png)\\n\\n---\\n\\n![image-20250603213233676](assets/image-20250603213233676.png)"}'),h={name:"AI人工智能/CodeBuddy AI 时代的智能编程伙伴/CodeBuddy AI 时代的智能编程伙伴.md"};function u(b,e,g,_,f,C){return n(),d("div",null,[...e[0]||(e[0]=[s("",31)])])}const A=a(h,[["render",u]]);export{I as __pageData,A as default};
